import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();

  // Design tokens
  const colors = {
    background: 0x0b0b10,
    surface: 0x101017,
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
  };

  // === FIELD PARTICLES (1200 instances) ===
  const fieldCount = 1200;
  const fieldGeometry = new THREE.IcosahedronGeometry(0.012, 2);

  const paperColor = new THREE.Color(colors.paper);
  const fieldMaterial = new THREE.MeshStandardMaterial({
    color: paperColor,
    metalness: 0,
    roughness: 1,
    emissive: paperColor,
    emissiveIntensity: 0.9,
    transparent: true,
  });

  const fieldMesh = new THREE.InstancedMesh(fieldGeometry, fieldMaterial, fieldCount);

  // Ellipsoidal distribution: 6 × 4 × 5 centered at [0, 0, -1.5]
  const ellipsoidCenter = new THREE.Vector3(0, 0, -1.5);
  const semiAxes = new THREE.Vector3(3, 2, 2.5);

  const fieldPositions = [];

  for (let i = 0; i < fieldCount; i++) {
    // Fibonacci sphere for uniform distribution
    const theta = Math.acos(1 - (2 * i) / fieldCount);
    const phi = Math.PI * (1 + Math.sqrt(5)) * i;

    let x = Math.sin(theta) * Math.cos(phi) * semiAxes.x;
    let y = Math.sin(theta) * Math.sin(phi) * semiAxes.y;
    let z = Math.cos(theta) * semiAxes.z;

    const pos = new THREE.Vector3(x, y, z).add(ellipsoidCenter);
    fieldPositions.push(pos);

    const matrix = new THREE.Matrix4();
    matrix.setPosition(pos);
    fieldMesh.setMatrixAt(i, matrix);
  }

  fieldMesh.instanceMatrix.needsUpdate = true;
  root.add(fieldMesh);

  // === ACCENT CORE (90 instances) ===
  const coreCount = 90;
  const coreGeometry = new THREE.IcosahedronGeometry(0.012, 2);

  const accentColor = new THREE.Color(colors.accent);
  const coreMaterial = new THREE.MeshStandardMaterial({
    color: accentColor,
    metalness: 0,
    roughness: 0.8,
    emissive: accentColor,
    emissiveIntensity: 1.8,
    transparent: true,
    blending: THREE.AdditiveBlending,
    fog: false,
  });

  const coreMesh = new THREE.InstancedMesh(coreGeometry, coreMaterial, coreCount);

  for (let i = 0; i < coreCount; i++) {
    const theta = Math.acos(1 - (2 * i) / coreCount);
    const phi = Math.PI * (1 + Math.sqrt(5)) * i;
    const radius = 0.5 * Math.cbrt(Math.random());

    const x = radius * Math.sin(theta) * Math.cos(phi);
    const y = radius * Math.sin(theta) * Math.sin(phi);
    const z = radius * Math.cos(theta);

    const matrix = new THREE.Matrix4();
    matrix.setPosition(x, y, z);
    coreMesh.setMatrixAt(i, matrix);
  }
  coreMesh.instanceMatrix.needsUpdate = true;
  root.add(coreMesh);

  // === FOG: linear fade from z=4 to z=10 ===
  root.fog = new THREE.Fog(colors.background, 4, 10);

  // === TEXT CONTENT ===
  const heroText = ctx.fontAtlas.render('NOVA ATELIER', {
    family: 'Lora',
    size: 124,
    weight: 600,
    color: colors.paper,
  });
  heroText.position.set(0, 0.5, 0.5);
  root.add(heroText);

  const subheadText = ctx.fontAtlas.render('Precision instruments for the dark hours.', {
    family: 'JetBrains Mono',
    size: 40,
    weight: 400,
    color: colors.paper,
  });
  subheadText.position.set(0, -0.25, 0.5);
  root.add(subheadText);

  const captionText = ctx.fontAtlas.render('EST. 2019 / GENEVA AND KYOTO', {
    family: 'JetBrains Mono',
    size: 18,
    weight: 400,
    color: colors.paper,
  });
  captionText.position.set(0, -2.25, 0.5);
  root.add(captionText);

  // === APPLY CINEMATIC PRIMITIVE: particle-emerge ===
  if (ctx.primitives?.['particle-emerge']) {
    ctx.primitives['particle-emerge'](fieldMesh, {
      count: fieldCount,
      durationMs: 1400,
    });
  }

  // === CORE PULSE ANIMATION (0.1 Hz sine, 1.5 to 1.8 intensity) ===
  const corePulseTimeline = gsap.timeline({ repeat: -1 });
  const pulsePeriod = 10; // 1 / 0.1 Hz

  corePulseTimeline
    .to(coreMaterial, {
      emissiveIntensity: 1.8,
      duration: pulsePeriod / 2,
      ease: 'sine.inOut',
    }, 0)
    .to(coreMaterial, {
      emissiveIntensity: 1.5,
      duration: pulsePeriod / 2,
      ease: 'sine.inOut',
    });

  // === AMBIENT DRIFT: orbital motion ±0.04 units at 0.05 Hz ===
  const driftPhases = fieldPositions.map(() => Math.random() * Math.PI * 2);
  const driftFreq = 0.05;
  const driftRadius = 0.04;

  const updateDrift = () => {
    const now = Date.now() * 0.001;
    for (let i = 0; i < fieldCount; i++) {
      const anchor = fieldPositions[i];
      const phase = driftPhases[i];
      const angle = 2 * Math.PI * driftFreq * now + phase;

      const offsetX = driftRadius * Math.cos(angle);
      const offsetY = driftRadius * Math.sin(angle);

      const driftMatrix = new THREE.Matrix4();
      driftMatrix.setPosition(
        anchor.x + offsetX,
        anchor.y + offsetY,
        anchor.z
      );
      fieldMesh.setMatrixAt(i, driftMatrix);
    }
    fieldMesh.instanceMatrix.needsUpdate = true;
  };

  const driftHandle = setInterval(updateDrift, 16);

  // === CLEANUP ===
  root.userData.cleanup = () => {
    clearInterval(driftHandle);
    gsap.killTweensOf(coreMaterial);
    corePulseTimeline.kill();

    fieldGeometry.dispose();
    fieldMaterial.dispose();
    coreGeometry.dispose();
    coreMaterial.dispose();
  };

  return root;
}
